CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522024403_InitialCreate') THEN
    CREATE TABLE "LicenseKeys" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Key" character varying(64) NOT NULL,
        "ClientName" character varying(200) NOT NULL,
        "Notes" text,
        "PlanName" text,
        "IsActive" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "ExpiresAt" timestamp with time zone,
        "LastValidatedAt" timestamp with time zone,
        CONSTRAINT "PK_LicenseKeys" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522024403_InitialCreate') THEN
    CREATE TABLE "SessionTokens" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Token" character varying(128) NOT NULL,
        "ClientName" character varying(200) NOT NULL,
        "IssuedAt" timestamp with time zone NOT NULL,
        "ExpiresAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_SessionTokens" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522024403_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_LicenseKeys_Key" ON "LicenseKeys" ("Key");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522024403_InitialCreate') THEN
    CREATE UNIQUE INDEX "IX_SessionTokens_Token" ON "SessionTokens" ("Token");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260522024403_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260522024403_InitialCreate', '10.0.8');
    END IF;
END $EF$;
COMMIT;

